  ["EV7_cairn_wind"] = {
    title = "Fireweed",
    flavor = "You find a flat stone and set it on the cairn. It settles with a click. The fireweed moves in the wind, and you go on.",
    effect = "",
    options = {},
  },
  ["EV7_trunks_cache"] = {
    title = "Before the Fire",
    flavor = "You go trunk to trunk, reaching into the hollows. In one, wrapped in oilcloth, are supplies someone hid before the fire and never came back for.",
    effect = "Party gains 2 random T0 Consumables and 10 gold.",
    options = {},
  },
  ["EV7_trunks_collapse"] = {
    title = "Chimney Fall",
    flavor = "You go trunk to trunk, reaching into the hollows. One gives way as you lean in, and comes down in a rush of ash and charcoal.",
    effect = "Leader takes 5% physical damage.",
    options = {},
  },
  ["EV7_trunks_wrens"] = {
    title = "Tenants",
    flavor = "You go trunk to trunk, reaching into the hollows. You get nothing but ash for your efforts.",
    effect = "Party gains \"Exhausted' status.",
    options = {},
  },
  ["EV8"] = {
    title = "Paid Through Autumn",
    template = "wilderness_template",
    flavor = "Beneath a low bough, a magnificently rotund mole sleeps beneath a blanket of ferns and mushrooms. Pinned to his coat is a tag: NO WAKE. PAID THROUGH AUTUMN. His pack, just out of reach, is unbuttoned.",
    effect = "",
    options = {
      {label = "Wake him.", tooltip = "", outcomes = {"EV8_wake_shortcut", "EV8_wake_shriek", "EV8_wake_notyet"}},
      {label = "Reach for the pack.", tooltip = "[AGI 1]", outcomes = {"EV8_pack_kit", "EV8_pack_kit", "EV8_pack_coin", "EV8_pack_spores"}},
      {label = "Nap beside him.", tooltip = "", outcomes = {"EV8_lie_rest", "EV8_lie_lost", "EV8_lie_snore"}},
      {label = "Leave him be.", tooltip = "", outcomes = {"EV8_leave_wave", "EV8_leave_stops"}},
    },
  },
  ["EV8_wake_shortcut"] = {
    title = "Been Expecting You",
    flavor = "Surprised that a mole would be in the Woodlands, you shake him by the shoulder. Sleepily, he blinks at you, unamused. He says he's been waiting for you specifically, and hands you a letter before returning to bed. Something about the letter makes you think the mole mistook you for someone else.",
    effect = "Party gains 1 \"Duchy Orders\".",
    options = {},
  },
  ["EV8_wake_shriek"] = {
    title = "A Lost Season",
    flavor = "Surprised that a mole would be in the Woodlands, you shake him by the shoulder. When he wakes, he is shocked to find that it's currently Spring. You leave the worker so that he could manage his affairs.",
    effect = "",
    options = {},
  },
  ["EV8_wake_notyet"] = {
    title = "Not Yet",
    flavor = "Surprised that a mole would be in the Woodlands, you shake him by the shoulder. He mutters, but refuses to wake.",
    effect = "Reset this event card and take another action (you can pick the same one again).",
    options = {},
  },
  ["EV8_pack_kit"] = {
    title = "Well Packed",
    flavor = "You reach past his snoring nose and ease the pack open. Inside are trail rations, a good knife, and a letter to his sister. You leave the letter.",
    effect = "Party gains 2 \"Duchy Trail Mix\" and 1 \"Hunting Knife\".",
    options = {},
  },
  ["EV8_pack_coin"] = {
    title = "Autumn's Wages",
    flavor = "You reach past his snoring nose and ease the pack open. A heavy purse sits on top. He was paid through autumn, after all.",
    effect = "Party gains 15 gold.",
    options = {},
  },
  ["EV8_pack_spores"] = {
    title = "Puff",
    flavor = "You reach past his snoring nose and ease the pack open. Your sleeve brushes a mushroom on his blanket, and it puffs a cloud of spores in your faces. The rest of the day passes in a yawning fog.",
    effect = "Party gains \"Exhausted' status.",
    options = {},
  },
  ["EV8_lie_rest"] = {
    title = "Dreamless",
    flavor = "You lie down in the ferns beside him and let his snoring carry you off. You sleep a dreamless hour and wake whole.",
    effect = "Party heals fully.",
    options = {},
  },
  ["EV8_lie_lost"] = {
    title = "A Day Gone",
    flavor = "You lie down in the ferns beside him and let his snoring carry you off. When you wake, rested at last, the mole is gone, and the light says a whole day has gone with him.",
    effect = "Party heals fully and decrement Time count.",
    options = {},
  },
  ["EV8_lie_snore"] = {
    title = "Noticed",
    flavor = "You lie down in the ferns beside him and let his snoring carry you off. Nothing much happens, though at one point the snoring changes pitch.",
    effect = "Party heals 1 health.",
    options = {},
  },
  ["EV8_leave_wave"] = {
    title = "Old Friend",
    flavor = "You let the mole sleep and walk on quietly. Behind you, the snoring continues.",
    effect = "Party gains 1 Favor.",
    options = {},
  },
  ["EV8_leave_stops"] = {
    title = "The Snoring Stops",
    flavor = "You let the mole sleep and walk on quietly. Behind you, the snoring stops.",
    effect = "Add \"Roaming Mole\" to Woodland event deck.",
    options = {},
  },
  ["EV9"] = {
    title = "Two Ferries",
    template = "wilderness_template",
    flavor = "Where the water is too wide to wade, two ferries wait on the near bank. One flies a Marquisate pennant and charges coin. The other is a large heron who'll carry you across for an amazing story, though she warns that she's heard most of them.",
    effect = "",
    options = {
      {label = "Pay the ferryman.", tooltip = "Party loses 2 gold per hero.", outcomes = {"EV9_ferry_stamp", "EV9_ferry_raid", "EV9_ferry_knee", "EV9_ferry_knee"}},
      {label = "Tell a story.", tooltip = "[CHA 1]", outcomes = {"EV9_heron_trade", "EV9_heron_sandbar", "EV9_heron_silent"}},
      {label = "Swim for it.", tooltip = "[All STR/AGI 1]", outcomes = {"EV9_swim_fast", "EV9_swim_fast", "EV9_swim_current"}},
    },
  },
  ["EV9_ferry_stamp"] = {
    title = "Stamped",
    flavor = "You pay the ferryman his coin and climb aboard under the Marquisate pennant. The crossing is smooth, and on the far bank he stamps your papers with a heavy seal.",
    effect = "",
    options = {},
  },
  ["EV9_ferry_raid"] = {
    title = "Midstream Raid",
    flavor = "You pay the ferryman his coin and climb aboard under the Marquisate pennant. Halfway across, Eyrie raiders drop out of the sky onto the deck. The commotion makes it impossible to reason with them.",
    effect = "Engage in combat.",
    options = {},
    spawn = {
      meeple = {{"faction Bird"}, {"faction Bird"}, {"faction Bird"}},
    },
  },
  ["EV9_ferry_knee"] = {
    title = "The Bad Knee",
    flavor = "You pay the ferryman his coin and climb aboard under the Marquisate pennant. You notice that the ferryman isn't a cat, but an old rabbit forced to pick a side. Your conversation gives him a brief but needed respite.",
    effect = "Party gains 1 Denizen reputation.",
    options = {},
  },
  ["EV9_heron_trade"] = {
    title = "A Story Back",
    flavor = "You climb onto the heron's back and start your story. She is amused by it. On the way across she tells you one in return, about the place you're headed.",
    effect = "The next time you leave this maptile to unknown space, draw 3 maptiles and pick 1.",
    options = {},
  },
  ["EV9_heron_sandbar"] = {
    title = "Heard It",
    flavor = "You climb onto the heron's back and start your story. She's heard it before. Halfway over she rudely drops you onto the sandbar below, and you spend the rest of the day wading, your food soaked through.",
    effect = "Decrement Time count and lose 3 Food Consumables, if able.",
    options = {},
  },
  ["EV9_heron_silent"] = {
    title = "Enamored",
    flavor = "You climb onto the heron's back and start your story. Immediately, she is hooked by the world setting. As you part ways, she promises to spread word of the \"Storyteller\".",
    effect = "Party gains 1 Denizen reputation.",
    options = {},
  },
  ["EV9_swim_fast"] = {
    title = "Ahead of Both",
    flavor = "You tie your packs tight and wade in. The water is cold but the current is kind, and you reach the far bank, though definitely after the ferry.",
    effect = "",
    options = {},
  },
  ["EV9_swim_current"] = {
    title = "The Current Takes",
    flavor = "You tie your packs tight and wade in. Halfway over, the current grabs at you. You all make it across. Not everything you carried does.",
    effect = "Party loses a random unequipped, non-Quest item.",
    options = {},
  },
  ["EV10"] = {
    title = "The Lit Window",
    template = "wilderness_template",
    flavor = "Set back from the rest, one house has been left to go wild. Its garden has gone to seed, and the fruit is rotting where it falls. One window is lit, and every few minutes a shadow crosses it, carrying something heavy.",
    effect = "",
    options = {
      {label = "Knock.", tooltip = "", outcomes = {"EV10_knock_badger", "EV10_knock_door", "EV10_knock_dark"}},
      {label = "Gather apples.", tooltip = "", outcomes = {"EV10_apples_sweet", "EV10_apples_wasps", "EV10_apples_mealy"}},
      {label = "Watch until dawn.", tooltip = "[STA 1]", outcomes = {"EV10_watch_cart", "EV10_watch_cart", "EV10_watch_trust", "EV10_watch_others"}},
    },
  },
  ["EV10_knock_badger"] = {
    title = "The Badger's Books",
    flavor = "You walk up through the weeds and knock. An old badger lets you in. She is hiding her books in the cellar before the Marquisate requisitions the house, and you carry boxes until late. She feeds you well for it.",
    effect = "Party heals 3. Party loses 1 day.",
    options = {},
  },
  ["EV10_knock_door"] = {
    title = "Opened Early",
    flavor = "You walk up through the weeds and knock. The door opens before you finish knocking, and whoever is behind it has been waiting for exactly this.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV10_knock_dark"] = {
    title = "Lights Out",
    flavor = "You walk up through the weeds and knock. The light goes out, and no one answers.",
    effect = "",
    options = {},
  },
  ["EV10_apples_sweet"] = {
    title = "High Branches",
    flavor = "You pick through the overgrown garden for apples. The ones on the ground are spoiled, but the ones high in the branches are still sweet.",
    effect = "Party gains 3 rations.",
    options = {},
  },
  ["EV10_apples_wasps"] = {
    title = "Wasps First",
    flavor = "You pick through the overgrown garden for apples. You find the wasps before you find the apples, and come away swollen, with a pocketful of fruit.",
    effect = "Party takes 1 damage. Party gains 1 ration.",
    options = {},
  },
  ["EV10_apples_mealy"] = {
    title = "Mealy",
    flavor = "You pick through the overgrown garden for apples. They're mealy, but they're filling.",
    effect = "Party gains 1 ration.",
    options = {},
  },
  ["EV10_watch_cart"] = {
    title = "Morning Cart",
    flavor = "You settle in across the lane and watch the window all night. At dawn an old badger comes out, struggling with a loaded cart. She pays you to help her get it down the road.",
    effect = "Party gains 4 gold per hero.",
    options = {},
  },
  ["EV10_watch_trust"] = {
    title = "Earned Trust",
    flavor = "You settle in across the lane and watch the window all night. At dawn an old badger comes out with a loaded cart. She saw you keep watch all night, decides you're the honest sort, and pays you with coin and something from the cart.",
    effect = "Party gains 15 gold and a random item.",
    options = {},
  },
  ["EV10_watch_others"] = {
    title = "Other Watchers",
    flavor = "You settle in across the lane and watch the window all night. Somewhere past midnight you realize you aren't the only ones watching, and the others have noticed you.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV11"] = {
    title = "The Painted Paw",
    template = "wilderness_template",
    flavor = "Among the trees, a young mouse is painting a sign on a tree: a circumscribed paw, raised and curled into a fist. She freezes when she sees you. Her brush is still dripping. Down the path, you can hear Marquisate boots.",
    effect = "",
    options = {
      {label = "Hide with her.", tooltip = "[All AGI 1]", outcomes = {"EV11_hide_acorn", "EV11_hide_slip"}},
      {label = "Finish her sign.", tooltip = "", outcomes = {"EV11_paint_spread", "EV11_paint_caught", "EV11_paint_missed"}},
      {label = "Step aside.", tooltip = "", outcomes = {"EV11_aside_papers", "EV11_aside_caught", "EV11_aside_ran"}},
    },
  },
  ["EV11_hide_acorn"] = {
    title = "Carved Acorn",
    flavor = "You pull her down into the undergrowth, and everyone holds still. The boots pass close enough to touch. When they're gone, she looks at you tearfully and presses a token into your hand before scurrying off.",
    effect = "Party gains 1 Alliance reputation.",
    options = {},
  },
  ["EV11_hide_slip"] = {
    title = "Gone Quiet",
    flavor = "You pull her down into the undergrowth, and everyone holds still. The boots pass close enough to touch. When you look up, she's gone without a word, and so is the brush.",
    effect = "",
    options = {},
  },
  ["EV11_paint_spread"] = {
    title = "Solo Painter",
    flavor = "You take the brush from her and set to work on the circle. She runs, and you finish it alone, giving enough time for the Marquisate guard to catch up with you. They shout at you and draw their swords.",
    effect = "Engage in combat.",
    options = {},
    spawn = {
      meeple = {{"faction Cat"}, {"faction Cat"}, {"faction Cat"}},
    },
  },
  ["EV11_paint_caught"] = {
    title = "Group Painting",
    flavor = "You take the brush from her and set to work on the circle. She's shocked as you finish the banner just in time as the Marquisate guards pass by. The guards draw their swords while the mouse flees, stealing glances behind her.",
    effect = "Party gains 1 Alliance reputation. Engage in combat.",
    options = {},
    spawn = {
      meeple = {{"faction Cat"}, {"faction Cat"}, {"faction Cat"}},
    },
  },
  ["EV11_paint_missed"] = {
    title = "Never Looked Up",
    flavor = "You take the brush from her and set to work on the circle. The patrol arrives before you're done, but marches right past you without ever really acknowledging you. She's shocked but notes your sympathy with the cause.",
    effect = "Party gains 1 Alliance reputation.",
    options = {},
  },
  ["EV11_aside_papers"] = {
    title = "Papers in Order",
    flavor = "You step off the path and let the patrol come to you. They check your papers, find them in order, and nod you on. \"This is heavy Alliance territory,\" remarks the lead patrol unit. \"Thanks for staying far away from them.\"",
    effect = "Party gains 1 Marquisate reputation.",
    options = {},
  },
  ["EV11_aside_caught"] = {
    title = "Behind You",
    flavor = "You step off the path and let the patrol come to you. While they read your papers, she bolts. Behind you, you hear them catch her.",
    effect = "",
    options = {},
  },
  ["EV11_aside_ran"] = {
    title = "She Ran",
    flavor = "You step off the path and let the patrol come to you. She runs before they reach you, prompting the patrol to run after. You never learn if she made it, but you do pocket what few goods left behind.",
    effect = "Party gains 3 gold and 1 \"Ration\".",
    options = {},
  },
  ["EV12"] = {
    title = "The Floating Market",
    template = "wilderness_template",
    flavor = "Six otter barges are lashed together across the water, making a market and a bridge at once. Everything is for sale, including passage. A sign at the gangplank lists prices for crossing, for news, and, in smaller letters, for not mentioning that you crossed.",
    effect = "",
    options = {
      {label = "Pay for passage.", tooltip = "Party loses 2 gold per hero.", outcomes = {"EV12_pass_receipt", "EV12_pass_tariff", "EV12_pass_done"}},
      {label = "Buy the news.", tooltip = "Party loses 3 gold.", outcomes = {"EV12_news_fresh", "EV12_news_stale", "EV12_news_hat"}},
      {label = "Pay for passage and silence.", tooltip = "Party loses 5 gold per hero.", outcomes = {"EV12_silence_held", "EV12_silence_outbid"}},
      {label = "Sell to the otters.", tooltip = "", outcomes = {"EV12_sell_trade"}},
    },
  },
  ["EV12_pass_receipt"] = {
    title = "Affairs in Order",
    flavor = "You pay at the gangplank and start across the barges. At the far end, a clerk stamps a receipt and hands it over.",
    effect = "",
    options = {},
  },
  ["EV12_pass_tariff"] = {
    title = "New Tariff",
    flavor = "You pay at the gangplank and start across the barges. Halfway across, a new sign goes up beside the old one. The second half of the crossing costs extra.",
    effect = "Party loses another 2 gold per hero; add \"Rumors Spread\" to the event deck.",
    options = {},
  },
  ["EV12_pass_done"] = {
    title = "Deal Done",
    flavor = "You pay at the gangplank and start across the barges. You cross, but the otters take a long look at you before allowing you to take the final step off land.",
    effect = "Add \"Rumors Spread\" to the event deck.",
    options = {},
  },
  ["EV12_news_fresh"] = {
    title = "Fresh News",
    flavor = "You pay an old otter by the rail, and she leans in close. She tells you who is camped on the road ahead, and where.",
    effect = "The next time you leave this maptile to unknown space, draw 3 maptiles and pick 1. Reset this event card and take another action (you can pick the same one again; reroll repeated outcomes).",
    options = {},
  },
  ["EV12_news_stale"] = {
    title = "Rumors of an Emissary",
    flavor = "You pay an old otter by the rail, and she leans in close. She swears there's an emissary from some northern kingdom here in the Woodland, particularly useful.",
    effect = "Party adds \"The Emissary\" quest. Reset this event card and take another action (you can pick the same one again; reroll repeated outcomes).",
    options = {},
  },
  ["EV12_news_hat"] = {
    title = "The Duchess's Hat",
    flavor = "You pay an old otter by the rail, and she leans in close. For the next hour, you hear a great deal about a duchess's missing hat. What news.",
    effect = "Reset this event card and take another action (you can pick the same one again; reroll repeated outcomes).",
    options = {},
  },
  ["EV12_silence_held"] = {
    title = "Never Seen You",
    flavor = "You slide the coins across, and the otter at the gangplank forgets your faces on the spot.",
    effect = "",
    options = {},
  },
  ["EV12_silence_outbid"] = {
    title = "Outbid",
    flavor = "You slide the coins across, and the otter at the gangplank forgets your faces on the spot. Later, someone pays her more to remember them. So much for the promises of Riverfolk.",
    effect = "Add \"Someone's Searching for You\" to event deck.",
    options = {},
  },
  ["EV12_sell_trade"] = {
    title = "Trade on the River",
    flavor = "You lay the item on a trader's counter and start to haggle.",
    effect = "Start trade with the \"Floating Market Merchant\". Reset this event card and take another action (you can pick the same one again; reroll repeated outcomes).",
    options = {},
  },
  ["EV13"] = {
    title = "The Garden of Let-Go Things",
    template = "wilderness_template",
    flavor = "Among the rubble, someone has made a garden out of things the war left behind: broken lanterns, a cracked shield, a child's shoe, all planted in neat rows. A lizard in a gray hood is watering them. She asks if you have anything you'd like to let go of.",
    effect = "",
    options = {
      {label = "Plant something.", tooltip = "Party loses an item of your choice.", outcomes = {"EV13_plant_lighter", "EV13_plant_regret", "EV13_plant_ledger"}},
      {label = "Ask what grows here.", tooltip = "", outcomes = {"EV13_ask_refuge", "EV13_ask_stay", "EV13_ask_answer"}},
      {label = "Dig something up.", tooltip = "", outcomes = {"EV13_take_shield", "EV13_take_hoods", "EV13_take_gone", "EV13_take_curse"}},
      {label = "Read her ledger.", tooltip = "[INT 2]", outcomes = {"EV13_ledger_relic", "EV13_ledger_rite"}},
    },
  },
  ["EV13_plant_lighter"] = {
    title = "Lighter",
    flavor = "You kneel in the rows and plant what you brought. The lizard pats the soil flat over it and waters it with the rest. You walk away lighter than you came.",
    effect = "Party adds the \"Cult Sightings\" quest and gains \"Lightened\" status.",
    options = {},
  },
  ["EV13_plant_regret"] = {
    title = "Second Thoughts",
    flavor = "You kneel in the rows and plant what you brought. You miss it as soon as the soil covers it, and she won't let you dig it back up.",
    effect = "Party adds the \"Cult Sightings\" quest.",
    options = {},
  },
  ["EV13_plant_ledger"] = {
    title = "Written Down",
    flavor = "You kneel in the rows and plant what you brought. She thanks you and writes its name in a ledger, on a line beneath all the others.",
    effect = "Party gains 1 Cult reputation and adds the \"Cult Sightings\" quest.",
    options = {},
  },
  ["EV13_ask_refuge"] = {
    title = "Open Door",
    flavor = "You ask the lizard what grows here. She tells you any garden of theirs will shelter an outcast, and shows you the mark to look for on the gate.",
    effect = "Party gains 1 Cult reputation and adds the \"Cult Sightings\" quest.",
    options = {},
  },
  ["EV13_ask_stay"] = {
    title = "Stay a While",
    flavor = "You ask the lizard what grows here. Instead of answering, she asks you to stay eeriely. When you refuse, the other hoods look up from the rows in unison. Unsettled, you quickly walk out of the garden unscathed.",
    effect = "Party adds the \"Cult Sightings\" quest and gains \"Omen\" status.",
    options = {},
  },
  ["EV13_ask_answer"] = {
    title = "Hope",
    flavor = "You ask the lizard what grows here. \"Hope,\" she says cryptically, \"it is all we need during this time.\" Strangely reassuring.",
    effect = "Party adds the \"Cult Sightings\" quest.",
    options = {},
  },
  ["EV13_take_shield"] = {
    title = "Still Holds",
    flavor = "You crouch at the end of a row and dig something up. It's battered and cracked, but it still holds.",
    effect = "Party gains a random T0 weapon or armor and adds the \"Cult Sightings\" quest.",
    options = {},
  },
  ["EV13_take_hoods"] = {
    title = "Garden Defense",
    flavor = "You crouch at the end of a row and dig something up. Every hood in the garden turns to look at you, and one by one they set down their watering cans.",
    effect = "Party adds the \"Cult Sightings\" quest and engages in combat.",
    options = {},
  },
  ["EV13_take_gone"] = {
    title = "Missing Goods",
    flavor = "You crouch at the end of a row and dig something up. She watches you take it and says nothing. In the morning it's gone from your pack, along with some other things.",
    effect = "Party adds the \"Cult Sightings\" quest and loses a random unequipped, non-Quest item.",
    options = {},
  },
  ["EV13_take_curse"] = {
    title = "Unearthed",
    flavor = "You crouch at the end of a row and dig something up. As the soil falls, you realize you're holding the skull of some unfortunate fox. She watches you and says nothing.",
    effect = "Party adds the \"Cult Sightings\" quest and gains \"Omen\" status.",
    options = {},
  },
  ["EV13_ledger_relic"] = {
    title = "The Relic Row",
    flavor = "Recognizing the inscription of the ledger by her waist, you ask to read it. Among the entries is a lost relic and the row where it was planted. She lets you dig it up.",
    effect = "Party adds the \"Cult Sightings\" quest and gains a random T1 weapon or armor.",
    options = {},
  },
  ["EV13_ledger_rite"] = {
    title = "The Rite",
    flavor = "Recognizing the inscription of the ledger by her waist, you ask to read it. In the margins is a rite of letting go. You understand it, and she can tell. She smiles and takes the ledger back.",
    effect = "Party adds the \"Cult Sightings\" quest and gains \"Lightened\" status.",
    options = {},
  },
  ["EV14"] = {
    title = "Four Cards on a Stump",
    template = "wilderness_template",
    flavor = "At a crossroads under the trees, a crow is laying four cards face down on a stump. He says one is a gift, one a debt, one a warning, and one is none of your business. He'll let you turn one over. He doesn't say what happens if you don't.",
    effect = "",
    options = {
      {label = "Randomly turn one over.", tooltip = "", outcomes = {"EV14_turn_gift", "EV14_turn_debt", "EV14_turn_warning", "EV14_turn_none"}},
      {label = "Ask who they're for.", tooltip = "", outcomes = {"EV14_ask_tap", "EV14_ask_you", "EV14_ask_tomorrow"}},
      {label = "Sweep them away.", tooltip = "", outcomes = {"EV14_sweep_seal1", "EV14_sweep_seal2", "EV14_sweep_seal3", "EV14_sweep_seal4"}},
      {label = "Watch his talons.", tooltip = "[AGI 2]", outcomes = {"EV14_watch_marked", "EV14_watch_debts"}},
    },
  },
  ["EV14_turn_gift"] = {
    title = "The Gift",
    flavor = "You pick a card and turn it over. It's a coupon with your name on it. The crow packs his things and flies away, before you get the chance to ask.",
    effect = "Party gains 1 \"Corvid Coupon\".",
    options = {},
  },
  ["EV14_turn_debt"] = {
    title = "The Debt",
    flavor = "You pick a card and turn it over. It's a debt signed in your own name, but not by a hand you recognize. Not wanting to fight, you quickly offer to settle the debt.",
    effect = "Party loses 3 gold.",
    options = {},
  },
  ["EV14_turn_warning"] = {
    title = "The Warning",
    flavor = "You pick a card and turn it over. It's a careful sketch of some future event, detailing the moments of great danger.",
    effect = "For the rest of the day, all damage effects from events are ignored.",
    options = {},
  },
  ["EV14_turn_none"] = {
    title = "None of Your Business",
    flavor = "You pick a card and turn it over. The crow takes it back before you can read it and flies away.",
    effect = "",
    options = {},
  },
  ["EV14_ask_tap"] = {
    title = "Silent",
    flavor = "You ask who the cards are for. He considers you, then taps one card with a talon.",
    effect = "Reset this event card and take another action (you cannot pick this same option again).",
    options = {},
  },
  ["EV14_ask_you"] = {
    title = "You",
    flavor = "You ask who the cards are for. \"You,\" he says, and slides one across the stump without turning it. As you read the card, suddenly the world around you transforms into a different scene all together. You're back on the road? Was that real?",
    effect = "Draw another event card.",
    options = {},
  },
  ["EV14_ask_tomorrow"] = {
    title = "Tomorrow",
    flavor = "You ask who the cards are for. \"For someone willing to play the game,\" growls the crow. No amount of convincing allows you to pick a card.",
    effect = "",
    options = {},
  },
  ["EV14_sweep_seal1"] = {
    title = "Eyrie Seal",
    flavor = "You sweep the cards off the stump. One lands face up, bearing the seal of the Eyrie Dynasty. As if expecting this to happen, the crow smirks. \"And so you have chosen.\" The bird's cryptic response leaves you worried all day.",
    effect = "Party loses 1 Dynasty reputation.",
    options = {},
  },
  ["EV14_sweep_seal2"] = {
    title = "Marquisate Orange",
    flavor = "You sweep the cards off the stump. One lands face up, bearing the striking orange of her majesty the Marquise. As if expecting this to happen, the crow smirks. \"And so you have chosen.\" The bird's cryptic response leaves you worried all day.",
    effect = "Party loses 1 Marquisate reputation.",
    options = {},
  },
  ["EV14_sweep_seal3"] = {
    title = "Raised Paw",
    flavor = "You sweep the cards off the stump. One lands face up, bearing the raised paw of the Alliance. As if expecting this to happen, the crow smirks. \"And so you have chosen.\" The bird's cryptic response leaves you worried all day.",
    effect = "",
    options = {},
  },
  ["EV14_sweep_seal4"] = {
    title = "Blank",
    flavor = "You sweep the cards off the stump. One lands face up, but it's completely blank. As if expecting this to happen, the crow smirks. \"And so you have chosen.\" The bird's cryptic response leaves you worried all day.",
    effect = "",
    options = {},
  },
  ["EV14_watch_marked"] = {
    title = "Scam Caught",
    flavor = "You watch the crow's movements and quickly realize that this is a scam of some sort. You threathen reporting him to the guards, but he quickly offers an apology before flying away.",
    effect = "Party gains 20 gold.",
    options = {},
  },
  ["EV14_watch_debts"] = {
    title = "Scam Caught",
    flavor = "You watch the crow's movements and quickly realize that this is a scam of some sort. You threathen reporting him to the guards. Calmly, the crow packs up his things and then flies away without another word.",
    effect = "",
    options = {},
  },
  ["EV15"] = {
    title = "The Hundred Pass By",
    template = "wilderness_template",
    flavor = "The undergrowth ahead has been trampled flat in a line a hundred paws wide. Rats are marching through it under a banner of stitched-together flags, singing. At the back, a small rat with a large sack collects anything the marchers drop. He has spotted your packs.",
    effect = "",
    options = {
      {label = "Join the march.", tooltip = "[All STA 1]", outcomes = {"EV15_march_crowd", "EV15_march_crowd", "EV15_march_song", "EV15_march_count"}},
      {label = "Pay the collector.", tooltip = "Party loses an item of your choice.", outcomes = {"EV15_give_badge", "EV15_give_more", "EV15_give_weigh"}},
      {label = "Hide in the brake.", tooltip = "", outcomes = {"EV15_hide_unseen", "EV15_hide_fire", "EV15_hide_afternoon"}},
      {label = "Pick up what falls.", tooltip = "", outcomes = {"EV15_trail_rare", "EV15_trail_bait", "EV15_trail_bait", "EV15_trail_buttons"}},
    },
  },
  ["EV15_march_crowd"] = {
    title = "Lost in the Crowd",
    flavor = "You fall in at the back of the column and match their step. Nobody questions you in the crowd, and the march covers ground faster than you ever could alone.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV15_march_song"] = {
    title = "The Song",
    flavor = "You fall in at the back of the column and match their step. You know the words by the second verse. At a bend you slip away, but the song stays stuck in your heads for days.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV15_march_count"] = {
    title = "Headcount",
    flavor = "You fall in at the back of the column and match their step. At the evening halt, the warlord counts heads and finds a few too many.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV15_give_badge"] = {
    title = "Tin Badge",
    flavor = "You hold out something from your packs, and the small rat takes it. He runs it up the line and comes back with a tin badge. Apparently you are friends of the Hundreds now.",
    effect = "Party gains 1 Hundreds reputation and a Tin Badge.",
    options = {},
  },
  ["EV15_give_more"] = {
    title = "Seconds",
    flavor = "You hold out something from your packs, and the small rat takes it. He turns it over, decides it isn't enough, and helps himself to a second thing.",
    effect = "Party loses a random item.",
    options = {},
  },
  ["EV15_give_weigh"] = {
    title = "Weighed",
    flavor = "You hold out something from your packs, and the small rat takes it. He weighs it in one paw, decides it will do, and goes.",
    effect = "",
    options = {},
  },
  ["EV15_hide_unseen"] = {
    title = "Unseen",
    flavor = "You push into the brake and lie flat. The march passes without a glance.",
    effect = "",
    options = {},
  },
  ["EV15_hide_fire"] = {
    title = "Burning the Edges",
    flavor = "You push into the brake and lie flat. The rearguard is burning the edges as it goes, and the fire finds you before they do. You crawl out singed and coughing.",
    effect = "Party takes 2 damage.",
    options = {},
  },
  ["EV15_hide_afternoon"] = {
    title = "All Afternoon",
    flavor = "You push into the brake and lie flat. It takes them all afternoon to pass, and you don't dare move until the singing fades.",
    effect = "Party loses 1 day.",
    options = {},
  },
  ["EV15_trail_rare"] = {
    title = "Too Fine",
    flavor = "You trail the march at a distance, picking through what the collector misses. In the trampled mud you find something far too fine to have belonged to any of them.",
    effect = "Party gains a rare item.",
    options = {},
  },
  ["EV15_trail_bait"] = {
    title = "Bait",
    flavor = "You trail the march at a distance, picking through what the collector misses. The shiniest thing on the trail was left there on purpose, and the rats beside it have been waiting for you.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV15_trail_buttons"] = {
    title = "Bones and Buttons",
    flavor = "You trail the march at a distance, picking through what the collector misses. They drop nothing but bones and buttons.",
    effect = "",
    options = {},
  },
  ["EV16"] = {
    title = "Cliffracers",
    template = "wilderness_template",
    flavor = "The path swings wide, and you realize the road has been climbing all morning. To your left, the ground drops away so steeply it's nearly a cliff. To your right, a battered but eager mouse is dragging two wooden sleds toward you. \"Last one down is a rotten egg!\"",
    effect = "",
    options = {
      {label = "Race him down.", tooltip = "[AGI 1]", outcomes = {"EV16_race_win", "EV16_race_tie", "EV16_race_fly"}},
      {label = "Pile onto his sled.", tooltip = "", outcomes = {"EV16_pile_glide", "EV16_pile_crash", "EV16_pile_pond", "EV16_pile_snap"}},
      {label = "Bet on the race.", tooltip = "[CHA 1]", outcomes = {"EV16_bet_charm", "EV16_bet_coin", "EV16_bet_path"}},
      {label = "Walk down instead.", tooltip = "", outcomes = {"EV16_long_wait", "EV16_long_view"}},
    },
  },
  ["EV16_race_win"] = {
    title = "First to the Bottom",
    flavor = "You grab one sled, he grabs the other, and you push off together. You beat him to the bottom by a whisker, well down the road. He hands over his lucky charm like it's a medal.",
    effect = "Party gains a random item. Party saves 1 day.",
    options = {},
  },
  ["EV16_race_tie"] = {
    title = "Tangled",
    flavor = "You grab one sled, he grabs the other, and you push off together. You hit the bottom at the same moment and tangle in a heap of runners and elbows. Everyone is bruised, and everyone is laughing, the mouse loudest of all.",
    effect = "Party takes 1 damage. Party gains 1 Favor.",
    options = {},
  },
  ["EV16_race_fly"] = {
    title = "Airborne",
    flavor = "You grab one sled, he grabs the other, and you push off together. Partway down, you hit a bump and leave the ground entirely. You land, somehow, a good way further down the road.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV16_pile_glide"] = {
    title = "Smooth Run",
    flavor = "You all pile onto one sled, the mouse at the front, and tip over the edge. It's the fastest you've ever moved, and nobody falls off.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV16_pile_crash"] = {
    title = "Rotten Eggs",
    flavor = "You all pile onto one sled, the mouse at the front, and tip over the edge. The sled was not built for this many. It reaches the bottom very quickly, though not with all of you still aboard.",
    effect = "Party takes 2 damage. Party saves 1 day.",
    options = {},
  },
  ["EV16_pile_pond"] = {
    title = "The Pond",
    flavor = "You all pile onto one sled, the mouse at the front, and tip over the edge. There's no way to steer and no way to stop, until a pond at the bottom stops you. A sack of rations sinks before anyone can grab it.",
    effect = "Party loses 1 ration. Party saves 1 day.",
    options = {},
  },
  ["EV16_pile_snap"] = {
    title = "Snapped Runner",
    flavor = "You all pile onto one sled, the mouse at the front, and tip over the edge. Halfway down, a runner snaps. The sled flips, and you tumble the rest of the way while your gear scatters down the slope.",
    effect = "Party takes 2 damage. Party loses a random item.",
    options = {},
  },
  ["EV16_bet_charm"] = {
    title = "Lucky Charm",
    flavor = "You agree to race, but only if he puts something on it. He bets his lucky charm, then loses it fair and square.",
    effect = "Party gains a random item.",
    options = {},
  },
  ["EV16_bet_coin"] = {
    title = "Pocket Money",
    flavor = "You agree to race, but only if he puts something on it. He turns out every pocket. It's more than you expected, and he loses all of it.",
    effect = "Party gains 15 gold.",
    options = {},
  },
  ["EV16_bet_path"] = {
    title = "A Confession",
    flavor = "You agree to race, but only if he puts something on it. He admits he has nothing to bet. Instead, he shows you the safe path down, which is quicker than the road anyway.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV16_long_wait"] = {
    title = "The Long Way",
    flavor = "You thank the mouse and take the long way down on foot. At the bottom, the mouse is waiting for you, battered and triumphant.",
    effect = "Party loses 1 day.",
    options = {},
  },
  ["EV16_long_view"] = {
    title = "Worth the View",
    flavor = "You thank the mouse and take the long way down on foot. It's slow, but from the slope you can see the road for miles, and everything moving on it.",
    effect = "Party loses 1 day. Look at the top 3 event cards and put them back in any order.",
    options = {},
  },
  ["EV17"] = {
    title = "The Survey Stakes",
    template = "wilderness_template",
    flavor = "Little flags on stakes run across the open ground in a perfect line, each stamped with the Duchy's seal. Where they cross your path, the ground is soft and freshly turned. A mole in spectacles surfaces beside a stake, looks at you, and asks you not to step there.",
    effect = "",
    options = {
      {label = "Step around.", tooltip = "", outcomes = {"EV17_around_fine", "EV17_around_fine", "EV17_around_noted"}},
      {label = "Step there anyway.", tooltip = "", outcomes = {"EV17_step_fall", "EV17_step_larder", "EV17_step_shouting", "EV17_step_shouting"}},
      {label = "Read the survey.", tooltip = "[INT 1]", outcomes = {"EV17_read_road", "EV17_read_error"}},
      {label = "Pull up a stake.", tooltip = "", outcomes = {"EV17_stake_sold", "EV17_stake_moles"}},
    },
  },
  ["EV17_around_fine"] = {
    title = "The Long Way Round",
    flavor = "You step around the soft ground, giving the stakes a wide berth. The mole tips his spectacles at you and sinks out of sight.",
    effect = "",
    options = {},
  },
  ["EV17_around_noted"] = {
    title = "Courtesy Noted",
    flavor = "You step around the soft ground, giving the stakes a wide berth. The mole writes your names on a slip of paper with a small nod and drops it down the hole.",
    effect = "Party gains 1 Duchy reputation.",
    options = {},
  },
  ["EV17_step_fall"] = {
    title = "Soft for a Reason",
    flavor = "You step onto the soft ground anyway. It gives way at once. You drop into a tunnel and climb out scraped and spitting dirt.",
    effect = "Party takes 1 damage.",
    options = {},
  },
  ["EV17_step_larder"] = {
    title = "The Larder",
    flavor = "You step onto the soft ground anyway. It gives way, and you drop straight into a tunnel storeroom. The mole is furious. The turnips are excellent.",
    effect = "Party gains 2 rations. Party loses 1 Duchy reputation.",
    options = {},
  },
  ["EV17_step_shouting"] = {
    title = "Ruined Survey",
    flavor = "You step onto the soft ground anyway. Nothing happens to you. Something happens to his survey, and he shouts after you for a long time.",
    effect = "Party loses 1 Duchy reputation.",
    options = {},
  },
  ["EV17_read_road"] = {
    title = "Tunnel Road",
    flavor = "You ask to see his survey, and he unrolls it reluctantly. The stakes mark a new tunnel road, and it runs your way. He lets you use it, as long as you wipe your feet.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV17_read_error"] = {
    title = "A Crooked Line",
    flavor = "You ask to see his survey, and he unrolls it reluctantly. You point out an error in his line. He's mortified, then grateful, and promises the Duchy won't forget it.",
    effect = "Party gains 1 Duchy reputation and 1 Favor.",
    options = {},
  },
  ["EV17_stake_sold"] = {
    title = "No Questions Asked",
    flavor = "You pull a stake out of the ground while the mole watches. Down the road, a Marquisate scout pays well for Duchy stakes and doesn't ask where you got it.",
    effect = "Party gains 15 gold. Party loses 1 Duchy reputation.",
    options = {},
  },
  ["EV17_stake_moles"] = {
    title = "Up From Below",
    flavor = "You pull a stake out of the ground while the mole watches. The mole vanishes down his hole. A moment later, moles come up all around you.",
    effect = "Party loses 1 Duchy reputation. Start a combat encounter.",
    options = {},
  },
  ["EV18"] = {
    title = "The Keepers' Dig",
    template = "wilderness_template",
    flavor = "At the bottom of a fresh pit among old stones, three badgers in iron caps are digging around something huge and green with age. Their leader leans on her shovel and looks you over. \"It's a relic,\" she says, \"and it's stuck, and you look like you've got arms.\"",
    effect = "",
    options = {
      {label = "Lift it free.", tooltip = "[STR 3]", outcomes = {"EV18_lift_piece", "EV18_lift_escort"}},
      {label = "Help them dig.", tooltip = "Decrement Time count.", outcomes = {"EV18_dig_paid", "EV18_dig_paid", "EV18_dig_cavein"}},
      {label = "Ask what it is.", tooltip = "", outcomes = {"EV18_ask_lore", "EV18_ask_old", "EV18_ask_nosy"}},
      {label = "Keep walking.", tooltip = "", outcomes = {"EV18_walk_shovels", "EV18_walk_rats"}},
    },
  },
  ["EV18_lift_piece"] = {
    title = "A Sound Like a Bell",
    flavor = "You climb down, set your shoulders against the relic, and heave. It comes free with a sound like a bell. A few pieces crack off, and the leader lets you keep the smallest.",
    effect = "Party gains a rare item and 1 Keepers reputation.",
    options = {},
  },
  ["EV18_lift_escort"] = {
    title = "Honor Guard",
    flavor = "You climb down, set your shoulders against the relic, and heave. It comes free with a sound like a bell. The leader insists on walking you out of the pit herself, relic and all, and her badgers keep watch over your camp that night.",
    effect = "Party gains 2 Keepers reputation. Party's next rest is safe.",
    options = {},
  },
  ["EV18_dig_paid"] = {
    title = "Fair Pay",
    flavor = "You take up spare shovels and dig with them until dark. Hard work, fair pay.",
    effect = "Party gains 4 gold per hero.",
    options = {},
  },
  ["EV18_dig_cavein"] = {
    title = "Cave-In",
    flavor = "You take up spare shovels and dig with them until dark. Late in the day, the pit wall slumps in on the dig. Everyone crawls out bruised, and she pays you all the same.",
    effect = "Party takes 2 damage. Party gains 4 gold per hero.",
    options = {},
  },
  ["EV18_ask_lore"] = {
    title = "A Long Answer",
    flavor = "You ask her what it is. She talks for an hour about the old roads and who used to walk them. Most of it turns out to be useful.",
    effect = "Look at the top 3 event cards and put them back in any order.",
    options = {},
  },
  ["EV18_ask_old"] = {
    title = "Old",
    flavor = "You ask her what it is. \"Old,\" she says, and goes back to digging.",
    effect = "",
    options = {},
  },
  ["EV18_ask_nosy"] = {
    title = "Too Many Questions",
    flavor = "You ask her what it is, then what it was for, then who buried it. She decides you ask too many questions.",
    effect = "Party loses 1 Keepers reputation.",
    options = {},
  },
  ["EV18_walk_shovels"] = {
    title = "Shovels Behind You",
    flavor = "You leave them to it and keep walking. Behind you, the shovels start up again.",
    effect = "",
    options = {},
  },
  ["EV18_walk_rats"] = {
    title = "Which Way",
    flavor = "You leave them to it and keep walking. A little way on, rats with picks stop you and pay you to say where the badgers are digging. You tell them.",
    effect = "Party gains 10 gold. Party loses 1 Keepers reputation.",
    options = {},
  },
  ["EV19"] = {
    title = "The Lily Town",
    template = "wilderness_template",
    flavor = "The trail ends at still water, and the water is full of frogs. They've built a town on the lilypads, rope bridges and all, and the only way across is through it. A frog in a reed hat is collecting names at the first pad. He looks very tired of collecting names.",
    effect = "",
    options = {
      {label = "Give your names.", tooltip = "", outcomes = {"EV19_names_stamped", "EV19_names_plain", "EV19_names_plain", "EV19_names_listed"}},
      {label = "Give false names.", tooltip = "", outcomes = {"EV19_false_fine", "EV19_false_caught"}},
      {label = "Trade news.", tooltip = "[CHA 1]", outcomes = {"EV19_news_supper", "EV19_news_raft"}},
      {label = "Go around the pond.", tooltip = "Decrement Time count.", outcomes = {"EV19_around_mud", "EV19_around_mud", "EV19_around_heron"}},
    },
  },
  ["EV19_names_stamped"] = {
    title = "Pond Ink",
    flavor = "You give him your names, one by one. He stamps each of your paws with pond ink and waves you through. The frogs on the bridges nod at the ink as you pass.",
    effect = "Party gains 1 Diaspora reputation.",
    options = {},
  },
  ["EV19_names_plain"] = {
    title = "Next",
    flavor = "You give him your names, one by one. He writes them down without looking up.",
    effect = "",
    options = {},
  },
  ["EV19_names_listed"] = {
    title = "On a List",
    flavor = "You give him your names, one by one. He pauses at one, checks it against another list, and waves you on without saying whose list it is.",
    effect = "Party gains 1 Pursuit.",
    options = {},
  },
  ["EV19_false_fine"] = {
    title = "Bramblewick",
    flavor = "You give him the first names that come to mind, starting with Bramblewick. He writes them down without looking up.",
    effect = "",
    options = {},
  },
  ["EV19_false_caught"] = {
    title = "Third Bramblewick Today",
    flavor = "You give him the first names that come to mind, starting with Bramblewick. \"That's the third Bramblewick today,\" he says, and sends you to the back of the line.",
    effect = "Party loses 1 Diaspora reputation and 1 day.",
    options = {},
  },
  ["EV19_news_supper"] = {
    title = "Starved for News",
    flavor = "You tell him what you've seen on the shore, and a crowd gathers to listen. The frogs are starved for news. They feed you, and argue about it all evening.",
    effect = "Party heals 2. Party gains 1 Diaspora reputation.",
    options = {},
  },
  ["EV19_news_raft"] = {
    title = "Lily-Raft",
    flavor = "You tell him what you've seen on the shore, and a crowd gathers to listen. He abandons the names entirely, calls a lily-raft, and poles you across himself.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV19_around_mud"] = {
    title = "Mud Bank",
    flavor = "You leave the frogs to their town and follow the bank around. It's muddy, and long.",
    effect = "",
    options = {},
  },
  ["EV19_around_heron"] = {
    title = "The Fisher",
    flavor = "You leave the frogs to their town and follow the bank around. On the far side, a heron is fishing. It looks at you the way it looks at frogs.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV20"] = {
    title = "Sideways Rain",
    template = "wilderness_template",
    flavor = "The horizon goes gray before the wind reaches you. Then the rain comes sideways. There's a cut in the bank big enough for maybe half of you, and somewhere off the road, a light that might be a window.",
    effect = "",
    options = {
      {label = "Run for the light.", tooltip = "", outcomes = {"EV20_light_inn", "EV20_light_moving", "EV20_light_strike"}},
      {label = "Cram into the hollow.", tooltip = "", outcomes = {"EV20_hollow_snug", "EV20_hollow_half", "EV20_hollow_half", "EV20_hollow_tenant"}},
      {label = "Weather it out.", tooltip = "[All STA 1]", outcomes = {"EV20_out_fresh", "EV20_out_branch"}},
    },
  },
  ["EV20_light_inn"] = {
    title = "Waystation",
    flavor = "You leave the road and run for the light, heads down against the rain. It's a waystation with a fire going. The keeper charges for space on the floor, and it's worth every coin.",
    effect = "Party loses 5 gold per hero. Party heals fully.",
    options = {},
  },
  ["EV20_light_moving"] = {
    title = "The Light Moves",
    flavor = "You leave the road and run for the light, heads down against the rain. The light moves. You chase it across sodden ground until the storm passes, and it never gets any closer.",
    effect = "Party is Exhausted. Party loses 1 day.",
    options = {},
  },
  ["EV20_light_strike"] = {
    title = "Too Close",
    flavor = "You leave the road and run for the light, heads down against the rain. Halfway there, lightning splits a tree beside you and throws you all into the mud.",
    effect = "Party takes 2 damage.",
    options = {},
  },
  ["EV20_hollow_snug"] = {
    title = "Snug",
    flavor = "You squeeze into the cut in the bank, packs and elbows and all. It fits more of you than it should.",
    effect = "",
    options = {},
  },
  ["EV20_hollow_half"] = {
    title = "Half Dry",
    flavor = "You squeeze into the cut in the bank, packs and elbows and all. Half of you stay dry. Half of you don't, and nobody gets any sleep.",
    effect = "Party is Exhausted.",
    options = {},
  },
  ["EV20_hollow_tenant"] = {
    title = "Already Taken",
    flavor = "You squeeze into the cut in the bank, packs and elbows and all. Something already lives at the back of it, and it has opinions.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV20_out_fresh"] = {
    title = "After the Rain",
    flavor = "You hunker down in the open and wait for the storm to pass. It passes eventually. Afterward, the air is clean, and the whole country smells new.",
    effect = "Add a Bless to the party deck.",
    options = {},
  },
  ["EV20_out_branch"] = {
    title = "Shaken Loose",
    flavor = "You hunker down in the open and wait for the storm to pass. The wind brings down a branch beside you, and someone's hidden purse comes down with it.",
    effect = "Party gains 15 gold.",
    options = {},
  },
  ["EV21"] = {
    title = "The Lightning Oak",
    template = "wilderness_template",
    flavor = "The oldest tree in sight has been split by lightning and is burning slowly from the inside, hissing in the rain. In the hollow at its heart, past the flames, something metal is catching the light.",
    effect = "",
    options = {
      {label = "Reach past the fire.", tooltip = "[STA 1]", outcomes = {"EV21_reach_hilt", "EV21_reach_tin"}},
      {label = "Wait for it to burn.", tooltip = "Decrement Time count.", outcomes = {"EV21_wait_lantern", "EV21_wait_lump", "EV21_wait_gone"}},
      {label = "Douse the fire.", tooltip = "", outcomes = {"EV21_douse_dormice", "EV21_douse_smoke", "EV21_douse_smoke", "EV21_douse_burn"}},
      {label = "Walk on.", tooltip = "", outcomes = {"EV21_walk_falls", "EV21_walk_ring"}},
    },
  },
  ["EV21_reach_hilt"] = {
    title = "Warm Hilt",
    flavor = "You wrap your arm in a cloak and reach in past the flames. The fire bites your leader's sleeve, but your fingers close on something heavy and well made, still warm from the heart of the tree.",
    effect = "Party gains a rare item. Leader takes 1 damage.",
    options = {},
  },
  ["EV21_reach_tin"] = {
    title = "Tin Box",
    flavor = "You wrap your arm in a cloak and reach in past the flames. Your fingers close on a tin box, hot to the touch. Inside are coins someone hid in the tree a long time ago.",
    effect = "Party gains 20 gold.",
    options = {},
  },
  ["EV21_wait_lantern"] = {
    title = "Cracked Lantern",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash. In the hollow, blackened but whole, is whatever the tree was keeping.",
    effect = "Party gains a random item.",
    options = {},
  },
  ["EV21_wait_lump"] = {
    title = "Was a Bell",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash. The thing in the hollow was a bell. Now it's a lump, though the metal will still sell.",
    effect = "Party gains 5 gold.",
    options = {},
  },
  ["EV21_wait_gone"] = {
    title = "Beaten to It",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash, and someone else has been and gone. Their tracks are fresh.",
    effect = "",
    options = {},
  },
  ["EV21_douse_dormice"] = {
    title = "Neighbors",
    flavor = "You haul water from the puddles and set to dousing the fire. Dormice watching from the next tree come down to help. When it's out, they thank you and show you what's inside.",
    effect = "Party gains 1 Favor and a random item.",
    options = {},
  },
  ["EV21_douse_smoke"] = {
    title = "All Smoke",
    flavor = "You haul water from the puddles and set to dousing the fire. You make a great deal of smoke and very little progress.",
    effect = "",
    options = {},
  },
  ["EV21_douse_burn"] = {
    title = "It Fights Back",
    flavor = "You haul water from the puddles and set to dousing the fire. The fire fights back, spitting sparks and hot sap until you give up, singed.",
    effect = "Party takes 1 damage.",
    options = {},
  },
  ["EV21_walk_falls"] = {
    title = "Down It Comes",
    flavor = "You leave the oak to burn and walk on. Behind you, it groans and comes down.",
    effect = "",
    options = {},
  },
  ["EV21_walk_ring"] = {
    title = "It Rang",
    flavor = "You leave the oak to burn and walk on. Behind you, it groans and comes down. Something inside rings like a bell as it lands, and you hear it long after you should be out of earshot.",
    effect = "Add a Curse to the party deck.",
    options = {},
  },
  ["EV22"] = {
    title = "Something Circling",
    template = "wilderness_template",
    flavor = "Your fire is down to coals when you hear it: footsteps, circling the camp, just past the light. They stop when you stop talking. They start again when you do.",
    effect = "",
    options = {
      {label = "Throw on more wood.", tooltip = "", outcomes = {"EV22_wood_fade", "EV22_wood_kit"}},
      {label = "Call out to it.", tooltip = "", outcomes = {"EV22_call_peddler", "EV22_call_rush", "EV22_call_quiet"}},
      {label = "Spot it first.", tooltip = "[AGI 1]", outcomes = {"EV22_spot_kit", "EV22_spot_weasel"}},
      {label = "Pretend to sleep.", tooltip = "", outcomes = {"EV22_sleep_acorn", "EV22_sleep_real", "EV22_sleep_wait"}},
    },
  },
  ["EV22_wood_fade"] = {
    title = "Nobody Sleeps",
    flavor = "You throw on more wood until the fire roars. The footsteps fade back into the dark. Nobody sleeps much after that.",
    effect = "Party is Exhausted.",
    options = {},
  },
  ["EV22_wood_kit"] = {
    title = "Working Up the Nerve",
    flavor = "You throw on more wood until the fire roars. In the bigger light you see a starving fox kit who has been working up the nerve to ask. You share your supper with her.",
    effect = "Party loses 1 ration. Party gains 1 Favor.",
    options = {},
  },
  ["EV22_call_peddler"] = {
    title = "Shy Peddler",
    flavor = "You call out into the dark. A peddler steps into the light, embarrassed, her pack still on her back. She sells you something before she goes, and does not lower her price.",
    effect = "Party loses 10 gold. Party gains a random item.",
    options = {},
  },
  ["EV22_call_rush"] = {
    title = "It Answers",
    flavor = "You call out into the dark. It answers by rushing the fire.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV22_call_quiet"] = {
    title = "Never Found Out",
    flavor = "You call out into the dark. The footsteps stop and don't start again. You never find out what it was.",
    effect = "",
    options = {},
  },
  ["EV22_spot_kit"] = {
    title = "Fox Kit",
    flavor = "You slip away from the fire and circle out after it. It's a starving fox kit, too scared to ask. You feed her, and by morning she has left a gift beside the coals.",
    effect = "Party loses 1 ration. Party gains 1 Favor and a random item.",
    options = {},
  },
  ["EV22_spot_weasel"] = {
    title = "Caught Halfway",
    flavor = "You slip away from the fire and circle out after it. You catch a weasel halfway into your packs. He bolts and leaves everything behind, his own purse included.",
    effect = "Party gains 15 gold.",
    options = {},
  },
  ["EV22_sleep_acorn"] = {
    title = "A Fair Trade",
    flavor = "You bank the fire, lie down, and pretend to sleep. Something creeps in, takes a ration, and leaves a single acorn in its place.",
    effect = "Party loses 1 ration.",
    options = {},
  },
  ["EV22_sleep_real"] = {
    title = "Too Convincing",
    flavor = "You bank the fire, lie down, and pretend to sleep. You pretend so well that you actually sleep, and nothing happens.",
    effect = "Party heals 2.",
    options = {},
  },
  ["EV22_sleep_wait"] = {
    title = "It Waited",
    flavor = "You bank the fire, lie down, and pretend to sleep. It waits until you're really asleep.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV23"] = {
    title = "The Beaver Dam",
    template = "wilderness_template",
    flavor = "A beaver dam has backed the stream up over the road. On top of it, an old beaver is shouting instructions at a young one, who is shouting back. Neither of them is fixing the leak spraying out of the middle.",
    effect = "",
    options = {
      {label = "Haul timber.", tooltip = "[STR 1]", outcomes = {"EV23_haul_fish", "EV23_haul_road"}},
      {label = "Fix the design.", tooltip = "[INT 1]", outcomes = {"EV23_design_thrilled", "EV23_design_thrilled", "EV23_design_offended"}},
      {label = "Wade the flood.", tooltip = "", outcomes = {"EV23_wade_cold", "EV23_wade_rations", "EV23_wade_burst"}},
      {label = "Settle the argument.", tooltip = "", outcomes = {"EV23_settle_young", "EV23_settle_old", "EV23_settle_both"}},
    },
  },
  ["EV23_haul_fish"] = {
    title = "Paid in Fish",
    flavor = "You haul timber up the dam and jam it into the leak. The spray slows, then stops. The old beaver pays you in smoked fish, and takes the credit.",
    effect = "Party gains 3 rations.",
    options = {},
  },
  ["EV23_haul_road"] = {
    title = "Road Clear",
    flavor = "You haul timber up the dam and jam it into the leak. The leak closes, and the water drops enough to clear the road.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV23_design_thrilled"] = {
    title = "He Knew That",
    flavor = "You study the dam and point out where it's weak. The young one is thrilled and has it patched in no time. The old one says he knew that.",
    effect = "Party gains 1 Favor. Party saves 1 day.",
    options = {},
  },
  ["EV23_design_offended"] = {
    title = "Deeply Offended",
    flavor = "You study the dam and point out where it's weak. The old beaver is deeply offended. The leak stays, on principle.",
    effect = "",
    options = {},
  },
  ["EV23_wade_cold"] = {
    title = "Knee-Deep",
    flavor = "You wade into the flood with your packs held high. It's knee-deep and cold, but passable.",
    effect = "",
    options = {},
  },
  ["EV23_wade_rations"] = {
    title = "Soggy",
    flavor = "You wade into the flood with your packs held high. Not high enough. Your rations don't survive the trip.",
    effect = "Party loses 2 rations.",
    options = {},
  },
  ["EV23_wade_burst"] = {
    title = "The Dam Gives",
    flavor = "You wade into the flood with your packs held high. Halfway across, the dam picks that moment to give. The water knocks you off your feet, and something from your packs goes downstream.",
    effect = "Party takes 1 damage. Party loses a random item.",
    options = {},
  },
  ["EV23_settle_young"] = {
    title = "The Young One",
    flavor = "You climb up between them to settle it. You side with the young one. The old one storms off, and the leak is fixed in a minute.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV23_settle_old"] = {
    title = "The Old One",
    flavor = "You climb up between them to settle it. You side with the old one. He's so pleased he forgets the leak entirely, and you wait half the day for the water to drop.",
    effect = "Party loses 1 day.",
    options = {},
  },
  ["EV23_settle_both"] = {
    title = "United Front",
    flavor = "You climb up between them to settle it. Before you can pick a side, they both turn on you.",
    effect = "",
    options = {},
  },
  ["EV24"] = {
    title = "Moss Helmets",
    template = "wilderness_template",
    flavor = "The ground here is quiet and overgrown. It takes a moment to see that the mounds under the moss are helmets, hundreds of them, cat and bird alike. Someone has been here recently. A path is worn between the mounds, and a few have been pried open.",
    effect = "",
    options = {
      {label = "Search the field.", tooltip = "", outcomes = {"EV24_search_blade", "EV24_search_taken", "EV24_search_scav", "EV24_search_rust"}},
      {label = "Follow the worn path.", tooltip = "", outcomes = {"EV24_path_widow", "EV24_path_camp", "EV24_path_out"}},
      {label = "Pay your respects.", tooltip = "", outcomes = {"EV24_respect_bless", "EV24_respect_quiet"}},
    },
  },
  ["EV24_search_blade"] = {
    title = "Never Drawn",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. Under one lies a sword still in its scabbard, never drawn.",
    effect = "Party gains a random item.",
    options = {},
  },
  ["EV24_search_taken"] = {
    title = "Not Yours",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. Beneath one, you find something worth keeping, and take it. Only later do you notice the name scratched inside.",
    effect = "Party gains a random item. Add a Curse to the party deck.",
    options = {},
  },
  ["EV24_search_scav"] = {
    title = "The Path-Makers",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. Before long, you meet whoever wore the path, and they don't care to share.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV24_search_rust"] = {
    title = "Rust and Moss",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. There's rust and moss, and nothing else.",
    effect = "",
    options = {},
  },
  ["EV24_path_widow"] = {
    title = "Every Week",
    flavor = "You follow the worn path between the mounds. It leads to an old cat who comes here every week. She asks you to help her find one helmet in particular, and you spend the day looking. When you find it, she sits down beside it.",
    effect = "Party loses 1 day. Party gains 2 Favors.",
    options = {},
  },
  ["EV24_path_camp"] = {
    title = "Scavenger Camp",
    flavor = "You follow the worn path between the mounds. It leads to a camp of scavengers, and they don't like visitors.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV24_path_out"] = {
    title = "Just a Path",
    flavor = "You follow the worn path between the mounds. It leads out of the field, and that's all.",
    effect = "",
    options = {},
  },
  ["EV24_respect_bless"] = {
    title = "Set Straight",
    flavor = "You set the pried helmets straight and stand a moment in silence. As you leave, a breeze stirs the moss on every mound at once.",
    effect = "Add a Bless to the party deck.",
    options = {},
  },
  ["EV24_respect_quiet"] = {
    title = "Quiet Glade",
    flavor = "You set the pried helmets straight and stand a moment in silence. The field stays quiet.",
    effect = "",
    options = {},
  },
  ["EV25"] = {
    title = "The Harvest Tug",
    template = "wilderness_template",
    flavor = "Two villages are holding their harvest fair in the same field, which nobody planned. Now there's a rope across the stubble, both sides are short a few haulers, and both mayors are looking at you. The prize is a wheel of cheese the size of a cart.",
    effect = "",
    options = {
      {label = "Pull for one side.", tooltip = "[All STR 1]", outcomes = {"EV25_tug_cheese", "EV25_tug_cheese", "EV25_tug_snap"}},
      {label = "Referee.", tooltip = "", outcomes = {"EV25_ref_fed", "EV25_ref_cheat", "EV25_ref_brawl"}},
      {label = "Bet on a side.", tooltip = "Party loses 10 gold.", outcomes = {"EV25_bet_win", "EV25_bet_cheese", "EV25_bet_lose", "EV25_bet_lose"}},
      {label = "Enjoy the fair.", tooltip = "Decrement Time count.", outcomes = {"EV25_fair_rest", "EV25_fair_rest", "EV25_fair_pockets"}},
    },
  },
  ["EV25_tug_cheese"] = {
    title = "Big Cheese",
    flavor = "You take up the rope for one village and dig in your heels. You win. The mayor carves you a good wedge of the cheese, and the whole village cheers your names.",
    effect = "Party gains 4 rations and 1 Favor.",
    options = {},
  },
  ["EV25_tug_snap"] = {
