    flavor = "You leave the rope to the villagers and spend the day at the fair. There are pies and music, and at night a soft patch of hay. In the morning your purses are lighter. Someone worked the crowd.",
    effect = "Party heals fully. Party loses 10 gold.",
    options = {},
  },
  ["EV26"] = {
    title = "The Voice in the Fog",
    template = "wilderness_template",
    flavor = "The fog comes up out of the ground until you can barely see your own paws. Somewhere ahead, someone is calling one of your names. It's the right name, said the right way, in a voice none of you know.",
    effect = "",
    options = {
      {label = "Follow the voice.", tooltip = "", outcomes = {"EV26_follow_poster", "EV26_follow_ahead", "EV26_follow_bait"}},
      {label = "Listen closely.", tooltip = "[AGI 2]", outcomes = {"EV26_listen_weasels", "EV26_listen_echo"}},
      {label = "Answer back.", tooltip = "", outcomes = {"EV26_answer_cousin", "EV26_answer_stops", "EV26_answer_found", "EV26_answer_found"}},
      {label = "Wait out the fog.", tooltip = "Decrement Time count.", outcomes = {"EV26_wait_empty", "EV26_wait_prints"}},
    },
  },
  ["EV26_follow_poster"] = {
    title = "Wanted",
    flavor = "You follow the voice into the fog. It belongs to an old mole who knows your name from a wanted poster and doesn't care. He leads you out by a shortcut.",
