    options = {},
  },
  ["EV26_follow_ahead"] = {
    title = "Always Ahead",
    flavor = "You follow the voice into the fog. It stays just ahead, however fast you walk. When the fog lifts, you're nowhere you meant to be.",
    effect = "Party loses 1 day.",
    options = {},
  },
  ["EV26_follow_bait"] = {
    title = "Bait",
    flavor = "You follow the voice into the fog. It leads you into a ring of shapes waiting in the fog. It was bait.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV26_listen_weasels"] = {
    title = "Two Voices",
    flavor = "You stand still and listen. There's a second voice, lower, feeding the first its lines. Two weasels in the fog. You walk wide around them.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV26_listen_echo"] = {
    title = "An Echo",
    flavor = "You stand still and listen. It's only an echo, carried a long way. Somewhere far off, someone is shouting your name, and they are looking for you.",
    effect = "Look at the top 3 event cards and put them back in any order.",
    options = {},
  },
  ["EV26_answer_cousin"] = {
    title = "Sent to Find You",
    flavor = "You call back. A young hare steps out of the fog, the cousin of someone you once helped. She was sent to find you.",
    effect = "Party gains 1 Favor.",
    options = {},
  },
  ["EV26_answer_stops"] = {
    title = "It Stops",
    flavor = "You call back. The calling stops.",
    effect = "",
    options = {},
  },
  ["EV26_answer_found"] = {
    title = "Now It Knows",
    flavor = "You call back. The calling stops. A moment later, much closer, it says your name again.",
    effect = "Party gains 1 Pursuit.",
    options = {},
  },
  ["EV26_wait_empty"] = {
    title = "Nobody There",
    flavor = "You sit tight and wait for the fog to lift. By noon it does, and nobody is there.",
    effect = "",
    options = {},
  },
  ["EV26_wait_prints"] = {
    title = "Close",
    flavor = "You sit tight and wait for the fog to lift. By noon it does. There are footprints all around your camp, close.",
    effect = "Add a Curse to the party deck.",
    options = {},
  },
  ["EV27"] = {
    title = "The Deserter",
    template = "wilderness_template",
    flavor = "A young Marquisate soldier is hiding in a ditch, armor half off, shaking. He begs you not to call out. Up the hill, his old company is breaking camp, and they're counting heads.",
    effect = "",
    options = {
      {label = "Hide him.", tooltip = "", outcomes = {"EV27_hide_tin", "EV27_hide_found", "EV27_hide_follows"}},
      {label = "Turn him in.", tooltip = "", outcomes = {"EV27_turn_bounty", "EV27_turn_look"}},
      {label = "Talk to the sergeant.", tooltip = "[CHA 1]", outcomes = {"EV27_sarge_dead", "EV27_sarge_dead", "EV27_sarge_price"}},
      {label = "Leave him to it.", tooltip = "", outcomes = {"EV27_leave_empty", "EV27_leave_shout"}},
    },
  },
  ["EV27_hide_tin"] = {
    title = "Short One",
    flavor = "You pile brush over the ditch and stand in front of it. The company counts, comes up one short, and marches on. He gives you the only thing he owns, his ration tin.",
    effect = "Party gains 2 rations. Party loses 1 Marquisate reputation.",
    options = {},
  },
  ["EV27_hide_found"] = {
    title = "Counted Again",
