    effect = "Party loses 1 Marquisate reputation. Start a combat encounter.",
    options = {},
  },
  ["EV27_hide_follows"] = {
    title = "Shadow",
    flavor = "You pile brush over the ditch and stand in front of it. When the company is gone, he won't leave your side. Then one morning he's gone too, with a thank-you scratched in the dirt.",
    effect = "Party gains 1 Favor.",
    options = {},
  },
  ["EV27_turn_bounty"] = {
    title = "Bounty",
    flavor = "You call up the hill, and the sergeant comes down for him. She counts out a bounty and doesn't look at either of you.",
    effect = "Party gains 15 gold and 1 Marquisate reputation.",
    options = {},
  },
  ["EV27_turn_look"] = {
