    flavor = "You climb the hill and find the sergeant before she finishes her count. You tell her you saw him fall in the last skirmish. She's relieved to believe it, and strikes his name.",
    effect = "Party gains 1 Favor and 1 Marquisate reputation.",
    options = {},
  },
  ["EV27_sarge_price"] = {
