    flavor = "You climb the hill and find the sergeant before she finishes her count. She agrees to list him as lost, for a price, and counts your coins more carefully than her soldiers.",
    effect = "Party loses 10 gold. Party gains 1 Favor.",
    options = {},
  },
  ["EV27_leave_empty"] = {
    title = "Empty Log",
    flavor = "You walk on and leave him in his ditch. When you look back, the ditch is empty.",
    effect = "",
    options = {},
  },
  ["EV27_leave_shout"] = {
    title = "The Shout",
    flavor = "You walk on and leave him in his ditch. Behind you, someone shouts, and you don't look back.",
    effect = "Add a Curse to the party deck.",
    options = {},
  },
  ["EV28"] = {
    title = "A Broken Wing",
    template = "wilderness_template",
    flavor = "A young Eyrie messenger lies in the ferns with one wing bent wrong, clutching a sealed letter to his chest. He's conscious, barely. The wax is red, and the ribbon is the kind only the Roost uses.",
    effect = "",
    options = {
      {label = "Splint his wing.", tooltip = "", outcomes = {"EV28_splint_name", "EV28_splint_name", "EV28_splint_bite"}},
      {label = "Break the cipher.", tooltip = "[INT 2]", outcomes = {"EV28_cipher_orders", "EV28_cipher_love"}},
      {label = "Take the letter.", tooltip = "", outcomes = {"EV28_take_sold", "EV28_take_hunted"}},
      {label = "Carry him to a post.", tooltip = "Decrement Time count.", outcomes = {"EV28_carry_paid", "EV28_carry_questions"}},
    },
  },
  ["EV28_splint_name"] = {
    title = "He'll Fly",
    flavor = "You straighten his wing as gently as you can and bind it to a splint. He'll fly again. Before you go, he tells you to give his name at any Eyrie post.",
    effect = "Party gains 2 Dynasty reputation.",
    options = {},
  },
  ["EV28_splint_bite"] = {
    title = "Ungrateful",
    flavor = "You straighten his wing as gently as you can and bind it to a splint. He doesn't trust you, and makes it known with his beak. He thanks you afterward, stiffly.",
    effect = "Leader takes 1 damage. Party gains 1 Dynasty reputation.",
    options = {},
  },
  ["EV28_cipher_orders"] = {
    title = "Troop Movements",
    flavor = "You ease the letter from his grip and work at the cipher while he dozes. It's troop movements for the next month. To the right buyer, it would be worth a great deal.",
    effect = "Party gains a Secret Letter.",
    options = {},
  },
  ["EV28_cipher_love"] = {
