      {label = "Scrub off a mark.", tooltip = "", outcomes = {"EV36_scrub_seen", "EV36_scrub_cheer"}},
      {label = "Take the bare road.", tooltip = "", outcomes = {"EV36_bare_quiet", "EV36_bare_quick", "EV36_bare_why"}},
    },
